"""Episode-specific direction for the supplied 115 cues; never a keyword router."""
import copy,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
ep=json.loads((ROOT/'episodes/ep02-composed.json').read_text())
opening=json.loads((ROOT/'episodes/ep02-first-minute-revised.json').read_text())
ep['beats'][:15]=copy.deepcopy(opening['beats'])
ep['beats'][14]['t1']=61
ep['id']='ep02-full-directed';ep['title']='AI কি আপনার চাকরি খাবে?'
ep['episodeNumber']='02';ep['cast']=opening['cast'];ep['directorVersion']=1
ep['directorStatus']='draft';ep['planningStatus']='authored'
ep['timing']['verified']=False
ep['timing']['note']='Supplied editorial timecodes preserved; not forced-aligned speech. Audio duration is authoritative.'
ep.pop('progressDuration',None)
V=ROOT/'reference/analysis/scene_stills'
refs={int(p.name.split('_')[1]):str(p.relative_to(ROOT)) for p in V.glob('*.jpg')}
PAPER='#E9E4D2';INK='#12141C';BLUE='#2F3BFF';RED='#FF3D17';GREY='#8A8CA0';GREEN='#216E50'
def O(typ,x,y=455,**kw):return dict(type=typ,x=x,y=y,instant=True,**kw)
def L(text,x=480,y=145,size=32,**kw):return O('label',x,y,text=text,size=size,maxWidth=790,**kw)
def A(x=230,y=455,action='explain',**kw):return O('person',x,y,h=kw.pop('h',165),action=action,**kw)
def G(x=230,y=455,action='explain',**kw):return A(x,y,action,role='guide',castId='guide',**kw)
def K(obj,field,start,end,duration=2,delay=0):obj['keyframes']=[{'at':delay,field:start},{'at':delay+duration,field:end}];return obj
def room(night=False):return [O('window',745,295,w=200,h=165,night=night),O('fan',470,130),O('plant',850,scale=.7)]
def desk(x=280,y=455,guide=False,ai=False,variant=0):return [G(x,y,'typing',h=150,pose='sit') if guide else A(x,y,'typing',h=150,pose='sit',variant=variant),O('desk',x+72,y,ai=ai)]
def crowd(n,x=220,y=455,step=45,h=120,action='listen',**kw):return [A(x+j*step,y,action,h=h,variant=j%6,phase=j*.67,**kw) for j in range(n)]
def tasks(names,x=470,y=340,ai=False):return [O('task',x+j*100,y,text=s,ai=ai,enter=j*.2) for j,s in enumerate(names)]
def grid(n,x,y=430,cols=10,active=None,color=BLUE,**kw):return O('grid',x,y,count=n,cols=cols,active=n if active is None else active,color=color,**kw)
def station(x,y=455,**kw):return O('office_station',x,y,s=1.1,**kw)
def office(n=3,ai=False):return [*room(),*[station(180+j*225,ai=ai,variant=j) for j in range(n)]]
def bars(values,labels,x=400,scale=2,color=BLUE):return [K(O('bar',x+j*220,430,w=80,h=v*scale,text=labels[j],color=color),'h',1,v*scale,1.4) for j,v in enumerate(values)]
def street():return [O('tea_stall',770,440),O('palm',590,360),O('building',130,365,label=''),O('rickshaw',430,440,scale=.55,motion={'kind':'walk','speed':12})]
def paper(text,x=600,y=355,w=280,h=150):return O('card',x,y,w=w,h=h,text=text,size=26)
def sewing(x=280):return [A(x,455,'sew',h=210,pose='sit',variant=2),O('sewing_table',x+115),O('sewing_feed',x+110,369),O('sewing_machine_active',x+110,377)]
def paircounts(a,b,la,lb):return [grid(a,220,cols=10),grid(b,580,cols=10),L(la,300,170),L(lb,660,170)]
def S(i,ref,backdrop,setting,action,change,objects,alt,hold=False):
 b=ep['beats'][i];b.update(scene='compose',cueIndex=i,scriptLine=ep['cues'][i]['text'],heading='',styleRefs=[refs[ref]],visualIntent=action+' '+change,
 shot={'backdrop':backdrop,'objects':objects,'links':[]})
 for j,o in enumerate(objects):o['id']=o.get('id',f'b{i:03}-o{j:02}')
 b['semanticAnalysis']={'actors':[o.get('castId',o.get('role','worker or participant')) for o in objects if o['type']=='person'],'action':action,'setting':setting,'facts':[b['scriptLine']],'relationship':change,'tone':'measured explanation; preserve conditional and approximate wording','negation':'Do not infer whole-job replacement from partial task automation; preserve the exact narration.','uncertainty':'Script claims and illustrative examples are retained, not independently verified.'}
 b['designDecision']={'alternatives':[action,alt],'mechanism':setting+' relationship','composition':action,'visibleChange':change,'actionPeak':change,'cameraPurpose':'Locked composition lets the action and its consequence remain readable.','transition':'Hard cut to the next narrated cue; retain the place when the argument continues.','why':action+' This shows the specific relationship in the narration without adding a new factual claim.'}
 b['referenceUse']=[f'Borrow the grounded scale, sparse line furniture, flat silhouettes, paper material and evidence hierarchy visible in {Path(refs[ref]).name}; draw this cue independently.']
 b['continuity']={'cast':'Guide uses the fixed vermilion identity; profession variants remain consistent within their location.','place':setting,'props':'Retain common desk, tool and document scale across this sequence.'}
 b['animationPlan']={'primaryAction':action,'motivation':change,'anticipation':'The acting hand or incoming evidence establishes its direction before the principal change.','contact':'Grounded people and furniture share the floor; carried objects use the named wrist socket. Diagrams use deliberate graphic placement.','weightShift':'Standing actors retain foot support; seated actors retain hip support and restrained upper-body movement.','actionPeak':change,'followThrough':'Settle the visible change and hold its result before the next cue.','secondaryMotion':'Offset worker gestures and restrained environmental fan or tool movement.','gaze':'Orient the actor toward the tool, conversation partner or evidence being explained.','cameraMotivation':'Hold the full relationship in view; avoid distracting decorative zooms.','intentionalHold':hold,'holdReason':'The conditional or evidence statement needs a quiet reading interval.' if hold else ''}
 b['review']={'start':'Pending actual rendered inspection.','middle':'Pending actual rendered inspection.','end':'Pending actual rendered inspection.','approved':False,'issues':[],'fixes':[]}

